  1→import { useState } from "react";
  2→import { useQuery } from "@tanstack/react-query";
  3→import { supabase } from "@/integrations/supabase/client";
  4→import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
  5→import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
  6→import { Button } from "@/components/ui/button";
  7→import { ChevronLeft, ChevronRight, Download } from "lucide-react";
  8→import { exportToCSV } from "@/lib/csvExport";
  9→
 10→const PAGE_SIZE = 20;
 11→
 12→const UsageLogsTab = () => {
 13→  const [page, setPage] = useState(0);
 14→
 15→  // Fetch user email map
 16→  const { data: userMap } = useQuery({
 17→    queryKey: ["admin_users"],
 18→    queryFn: async () => {
 19→      const { data, error } = await supabase.functions.invoke("admin-users", { method: "GET" });
 20→      if (error) throw error;
 21→      const map: Record<string, string> = {};
 22→      (data as any[])?.forEach((u) => { map[u.id] = u.email; });
 23→      return map;
 24→    },
 25→    staleTime: 5 * 60 * 1000,
 26→  });
 27→
 28→  const { data } = useQuery({
 29→    queryKey: ["admin_usage_logs", page],
 30→    queryFn: async () => {
 31→      const from = page * PAGE_SIZE;
 32→      const to = from + PAGE_SIZE - 1;
 33→      const { data, error, count } = await supabase
 34→        .from("usage_logs")
 35→        .select("*", { count: "exact" })
 36→        .order("created_at", { ascending: false })
 37→        .range(from, to);
 38→      if (error) throw error;
 39→      return { logs: data, total: count ?? 0 };
 40→    },
 41→  });
 42→
 43→  const totalPages = Math.ceil((data?.total ?? 0) / PAGE_SIZE);
 44→
 45→  const handleExport = () => {
 46→    if (!data?.logs?.length) return;
 47→    const rows = data.logs.map((l: any) => ({
 48→      user: userMap?.[l.user_id] || l.user_id,
 49→      job_id: l.job_id || "",
 50→      credits_used: l.credits_used,
 51→      date: new Date(l.created_at).toISOString(),
 52→    }));
 53→    exportToCSV(rows, "usage-logs");
 54→  };
 55→
 56→  return (
 57→    <Card>
 58→      <CardHeader className="flex flex-row items-center justify-between pb-3">
 59→        <CardTitle className="text-lg">Usage Logs</CardTitle>
 60→        <div className="flex items-center gap-3">
 61→          <Button variant="outline" size="sm" onClick={handleExport} disabled={!data?.logs?.length}>
 62→            <Download className="h-4 w-4 mr-1" />CSV
 63→          </Button>
 64→          <div className="flex items-center gap-2 text-sm text-muted-foreground">
 65→            Page {page + 1} of {Math.max(totalPages, 1)}
 66→            <Button variant="outline" size="icon" className="h-7 w-7" disabled={page === 0} onClick={() => setPage(p => p - 1)}>
 67→              <ChevronLeft className="h-3.5 w-3.5" />
 68→            </Button>
 69→            <Button variant="outline" size="icon" className="h-7 w-7" disabled={page >= totalPages - 1} onClick={() => setPage(p => p + 1)}>
 70→              <ChevronRight className="h-3.5 w-3.5" />
 71→            </Button>
 72→          </div>
 73→        </div>
 74→      </CardHeader>
 75→      <CardContent className="p-0">
 76→        <Table>
 77→          <TableHeader>
 78→            <TableRow>
 79→              <TableHead>User</TableHead>
 80→              <TableHead>Job ID</TableHead>
 81→              <TableHead>Credits Used</TableHead>
 82→              <TableHead>Date</TableHead>
 83→            </TableRow>
 84→          </TableHeader>
 85→          <TableBody>
 86→            {data?.logs?.map((l: any) => (
 87→              <TableRow key={l.id}>
 88→                <TableCell className="text-sm" title={l.user_id}>
 89→                  {userMap?.[l.user_id] || l.user_id?.slice(0, 8) + "…"}
 90→                </TableCell>
 91→                <TableCell className="font-mono text-xs">{l.job_id?.slice(0, 8) ?? "—"}</TableCell>
 92→                <TableCell>{l.credits_used}</TableCell>
 93→                <TableCell className="text-sm">{new Date(l.created_at).toLocaleString()}</TableCell>
 94→              </TableRow>
 95→            ))}
 96→          </TableBody>
 97→        </Table>
 98→      </CardContent>
 99→    </Card>
100→  );
101→};
102→
103→export default UsageLogsTab;
