 17→interface AuditLog {
 18→  id: string;
 19→  admin_user_id: string;
 20→  action: string;
 21→  entity_type: string;
 22→  entity_id: string | null;
 23→  details: Record<string, any>;
 24→  created_at: string;
 25→}
