 27→const PAGE_SIZE = 30;
 28→
 29→const actionColors: Record<string, string> = {
 30→  create: "bg-emerald-100 text-emerald-800 dark:bg-emerald-900 dark:text-emerald-200",
 31→  update: "bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200",
 32→  delete: "bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200",
