 35→  unban: "bg-emerald-100 text-emerald-800 dark:bg-emerald-900 dark:text-emerald-200",
 36→};
 37→
 38→function getActionColor(action: string) {
 39→  const verb = action.split(".").pop() ?? "";
 40→  return actionColors[verb] ?? "";
 41→}
