 43→const AuditLogsTab = () => {
 44→  const [entityFilter, setEntityFilter] = useState("all");
 45→  const [search, setSearch] = useState("");
 46→  const [page, setPage] = useState(0);
 47→  const [dateFrom, setDateFrom] = useState<Date | undefined>();
 48→  const [dateTo, setDateTo] = useState<Date | undefined>();
 49→
 50→  const { data: logs, isLoading } = useQuery({
 51→    queryKey: ["admin_audit_logs"],
 52→    queryFn: async () => {
 53→      const { data, error } = await (supabase as any)
 54→        .from("admin_audit_logs")
 55→        .select("*")
 56→        .order("created_at", { ascending: false })
 57→        .limit(500);
 58→      if (error) throw error;
 59→      return data as AuditLog[];
 60→    },
 61→  });
 62→
 63→  const { data: adminUsers } = useQuery({
 64→    queryKey: ["admin_users_for_audit"],
 65→    queryFn: async () => {
 66→      const { data, error } = await supabase.functions.invoke("admin-users", { method: "GET" });
 67→      if (error) throw error;
 68→      return data as { id: string; email: string }[];
 69→    },
 70→  });
 71→
 72→  const emailMap = useMemo(() => {
 73→    const map = new Map<string, string>();
 74→    adminUsers?.forEach((u) => map.set(u.id, u.email));
 75→    return map;
 76→  }, [adminUsers]);
 77→
 78→  const filtered = logs?.filter((l) => {
 79→    const matchesEntity = entityFilter === "all" || l.entity_type === entityFilter;
 80→    const matchesSearch = !search || 
 81→      l.action.toLowerCase().includes(search.toLowerCase()) ||
 82→      l.entity_id?.toLowerCase().includes(search.toLowerCase()) ||
 83→      JSON.stringify(l.details).toLowerCase().includes(search.toLowerCase());
 84→    const logDate = new Date(l.created_at);
 85→    const matchesFrom = !dateFrom || logDate >= startOfDay(dateFrom);
 86→    const matchesTo = !dateTo || logDate <= endOfDay(dateTo);
 87→    return matchesEntity && matchesSearch && matchesFrom && matchesTo;
 88→  }) ?? [];
 89→
 90→  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);
 91→  const paged = filtered.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);
 92→
 93→  const entityTypes = [...new Set(logs?.map((l) => l.entity_type) ?? [])];
 94→
 95→  return (
 96→    <div className="space-y-4">
 97→      <h2 className="text-xl font-semibold flex items-center gap-2">
 98→        <ClipboardList className="h-5 w-5" /> Audit Logs
 99→      </h2>
100→
101→      <Card>
102→        <CardHeader className="pb-3">
103→          <div className="flex items-center gap-2 flex-wrap">
104→            <div className="relative">
105→              <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
106→              <Input
107→                placeholder="Search actions…"
108→                value={search}
109→                onChange={(e) => { setSearch(e.target.value); setPage(0); }}
110→                className="pl-8 w-[200px]"
111→              />
112→            </div>
113→            <Select value={entityFilter} onValueChange={(v) => { setEntityFilter(v); setPage(0); }}>
114→              <SelectTrigger className="w-[150px]"><SelectValue placeholder="Entity" /></SelectTrigger>
115→              <SelectContent>
116→                <SelectItem value="all">All Entities</SelectItem>
117→                {entityTypes.map((e) => <SelectItem key={e} value={e}>{e}</SelectItem>)}
118→              </SelectContent>
119→            </Select>
120→            <Badge variant="outline" className="text-xs">{filtered.length} entries</Badge>
121→
122→            {/* Preset date ranges */}
123→            {[
124→              { label: "Today", from: startOfToday(), to: new Date() },
125→              { label: "7 days", from: subDays(new Date(), 7), to: new Date() },
126→              { label: "30 days", from: subDays(new Date(), 30), to: new Date() },
127→            ].map((preset) => (
128→              <Button
129→                key={preset.label}
130→                variant="outline"
131→                size="sm"
132→                className="text-xs h-7"
133→                onClick={() => { setDateFrom(preset.from); setDateTo(preset.to); setPage(0); }}
134→              >
135→                {preset.label}
136→              </Button>
137→            ))}
138→
139→            {/* Date range pickers */}
140→            <Popover>
141→              <PopoverTrigger asChild>
142→                <Button variant="outline" size="sm" className={cn("gap-1", !dateFrom && "text-muted-foreground")}>
143→                  <CalendarIcon className="h-3.5 w-3.5" />
144→                  {dateFrom ? format(dateFrom, "MMM d, yyyy") : "From"}
145→                </Button>
146→              </PopoverTrigger>
147→              <PopoverContent className="w-auto p-0" align="start">
148→                <Calendar mode="single" selected={dateFrom} onSelect={(d) => { setDateFrom(d); setPage(0); }} initialFocus className="p-3 pointer-events-auto" />
149→              </PopoverContent>
150→            </Popover>
151→            <Popover>
152→              <PopoverTrigger asChild>
153→                <Button variant="outline" size="sm" className={cn("gap-1", !dateTo && "text-muted-foreground")}>
154→                  <CalendarIcon className="h-3.5 w-3.5" />
155→                  {dateTo ? format(dateTo, "MMM d, yyyy") : "To"}
156→                </Button>
157→              </PopoverTrigger>
158→              <PopoverContent className="w-auto p-0" align="start">
159→                <Calendar mode="single" selected={dateTo} onSelect={(d) => { setDateTo(d); setPage(0); }} initialFocus className="p-3 pointer-events-auto" />
160→              </PopoverContent>
161→            </Popover>
162→            {(dateFrom || dateTo) && (
163→              <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => { setDateFrom(undefined); setDateTo(undefined); setPage(0); }}>
164→                <X className="h-3.5 w-3.5" />
165→              </Button>
166→            )}
167→            <Button
168→              variant="outline"
169→              size="sm"
170→              disabled={filtered.length === 0}
171→              onClick={() => exportToCSV(
172→                filtered.map((l) => ({
173→                  time: format(new Date(l.created_at), "yyyy-MM-dd HH:mm:ss"),
174→                  admin: emailMap.get(l.admin_user_id) ?? l.admin_user_id,
175→                  action: l.action,
176→                  entity_type: l.entity_type,
177→                  entity_id: l.entity_id ?? "",
178→                  details: JSON.stringify(l.details),
179→                })),
180→                "audit-logs"
181→              )}
182→            >
183→              <Download className="h-3.5 w-3.5 mr-1" />Export CSV
184→            </Button>
185→          </div>
186→        </CardHeader>
187→        <CardContent className="p-0">
188→          <Table>
189→            <TableHeader>
190→              <TableRow>
191→                <TableHead>Time</TableHead>
192→                <TableHead>Admin</TableHead>
193→                <TableHead>Action</TableHead>
194→                <TableHead>Entity</TableHead>
195→                <TableHead>Entity ID</TableHead>
196→                <TableHead>Details</TableHead>
197→              </TableRow>
198→            </TableHeader>
199→            <TableBody>
200→              {isLoading ? (
201→                <TableRow><TableCell colSpan={6} className="text-center py-8 text-muted-foreground">Loading…</TableCell></TableRow>
202→              ) : paged.length === 0 ? (
203→                <TableRow><TableCell colSpan={6} className="text-center py-8 text-muted-foreground">No audit logs found</TableCell></TableRow>
204→              ) : paged.map((l) => (
205→                <TableRow key={l.id}>
206→                  <TableCell className="text-xs text-muted-foreground whitespace-nowrap">
207→                    {format(new Date(l.created_at), "MMM d, HH:mm:ss")}
208→                  </TableCell>
209→                  <TableCell className="text-xs text-muted-foreground whitespace-nowrap">
210→                    {emailMap.get(l.admin_user_id) ?? l.admin_user_id.slice(0, 8) + "…"}
211→                  </TableCell>
212→                  <TableCell>
213→                    <Badge variant="secondary" className={`text-xs ${getActionColor(l.action)}`}>
214→                      {l.action}
215→                    </Badge>
216→                  </TableCell>
217→                  <TableCell className="text-sm">{l.entity_type}</TableCell>
218→                  <TableCell className="text-xs font-mono text-muted-foreground max-w-[120px] truncate">
219→                    {l.entity_id ?? "—"}
220→                  </TableCell>
221→                  <TableCell className="text-xs text-muted-foreground max-w-[250px] truncate">
222→                    {Object.keys(l.details).length > 0 ? JSON.stringify(l.details) : "—"}
223→                  </TableCell>
224→                </TableRow>
225→              ))}
226→            </TableBody>
227→          </Table>
228→          {totalPages > 1 && (
229→            <div className="flex items-center justify-between px-4 py-3 border-t border-border">
230→              <span className="text-sm text-muted-foreground">Page {page + 1} of {totalPages}</span>
231→              <div className="flex items-center gap-2">
232→                <Button variant="outline" size="icon" className="h-7 w-7" disabled={page === 0} onClick={() => setPage(p => p - 1)}>
233→                  <ChevronLeft className="h-3.5 w-3.5" />
234→                </Button>
235→                <Button variant="outline" size="icon" className="h-7 w-7" disabled={page >= totalPages - 1} onClick={() => setPage(p => p + 1)}>
236→                  <ChevronRight className="h-3.5 w-3.5" />
237→                </Button>
238→              </div>
239→            </div>
240→          )}
241→        </CardContent>
242→      </Card>
243→    </div>
244→  );
245→};
246→
247→export default AuditLogsTab;
